/*__ESM_BODY_START__*/window.process={};import{j as jsxRuntimeExports}from"./main.jsdbx";import{i as insertStyle}from"./____insertStyle.jsdbx";insertStyle(".nav-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 background: #060911;
 border-bottom: 1px solid var(--cc-border, #1e2a45);
 padding: 0 24px;
 height: 56px;
 position: sticky;
 top: 0;
 z-index: 100;
}

.nav-header__left {
 display: flex;
 align-items: center;
}

.nav-header__logo {
 display: flex;
 align-items: center;
 gap: 10px;
}

.nav-header__logo-icon {
 width: 28px;
 height: 28px;
 border-radius: 50%;
 background: var(--cc-accent, #00c896);
}

.nav-header__logo-text {
 font-size: 16px;
 font-weight: 700;
 color: var(--cc-text-primary, #e2e8f0);
 letter-spacing: -0.3px;
}

.nav-header__logo-divider {
 color: var(--cc-text-secondary, #94a3b8);
 font-weight: 300;
 margin: 0 2px;
}

.nav-header__logo-subtitle {
 font-size: 11px;
 font-weight: 600;
 color: var(--cc-text-secondary, #94a3b8);
 letter-spacing: 1.2px;
 text-transform: uppercase;
}

.nav-header__center {
 display: flex;
 align-items: center;
 gap: 4px;
 background: rgba(255, 255, 255, 0.05);
 border-radius: 8px;
 padding: 4px;
}

.nav-header__tab {
 padding: 6px 16px;
 border-radius: 6px;
 font-size: 13px;
 font-weight: 500;
 color: var(--cc-text-secondary, #94a3b8);
 text-decoration: none;
 transition: all 0.2s ease;
}

.nav-header__tab:hover {
 color: var(--cc-text-primary, #e2e8f0);
}

.nav-header__tab--active {
 background: #ffffff;
 color: #0a0e1a;
 font-weight: 600;
}

.nav-header__right {
 display: flex;
 align-items: center;
 gap: 12px;
}

.nav-header__search {
 display: flex;
 align-items: center;
 gap: 8px;
 background: rgba(255, 255, 255, 0.05);
 border: 1px solid var(--cc-border, #1e2a45);
 border-radius: 8px;
 padding: 6px 12px;
}

.nav-header__search-icon {
 color: var(--cc-text-secondary, #94a3b8);
 flex-shrink: 0;
}

.nav-header__search-input {
 background: none;
 border: none;
 outline: none;
 color: var(--cc-text-primary, #e2e8f0);
 font-size: 12px;
 width: 180px;
}

.nav-header__search-input::placeholder {
 color: var(--cc-text-secondary, #94a3b8);
}

.nav-header__icon-btn {
 display: flex;
 align-items: center;
 gap: 6px;
 background: none;
 border: none;
 color: var(--cc-text-secondary, #94a3b8);
 cursor: pointer;
 padding: 6px;
 border-radius: 6px;
 position: relative;
}

.nav-header__icon-btn:hover {
 color: var(--cc-text-primary, #e2e8f0);
}

.nav-header__badge {
 position: absolute;
 top: 0;
 right: 0;
 background: var(--cc-critical, #ef4444);
 color: #fff;
 font-size: 9px;
 font-weight: 700;
 width: 16px;
 height: 16px;
 border-radius: 50%;
 display: flex;
 align-items: center;
 justify-content: center;
}

.nav-header__calendar-text {
 font-size: 12px;
 color: var(--cc-text-secondary, #94a3b8);
}

.nav-header__avatar {
 width: 32px;
 height: 32px;
 border-radius: 50%;
 background: linear-gradient(135deg, #6366f1, #8b5cf6);
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 11px;
 font-weight: 700;
 color: #fff;
